#!/usr/bin/env python3
from pathlib import Path
import re

ROOT = Path.cwd()

def read(rel):
    p = ROOT / rel
    if not p.is_file():
        raise RuntimeError(f"missing {rel}")
    return p.read_text(encoding="utf-8")

def write(rel, text):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding="utf-8")

def rep(text, old, new, rel, label, count=1):
    got = text.count(old)
    if got != count:
        raise RuntimeError(f"{rel}: {label}: expected {count}, got {got}")
    return text.replace(old, new, count)

def sub(text, pattern, repl, rel, label, count=1, flags=re.S):
    out, n = re.subn(pattern, lambda _m: repl, text, count=count, flags=flags)
    if n != count:
        raise RuntimeError(f"{rel}: {label}: expected {count}, got {n}")
    return out

# 1) Dynamic judging schema + selectable built-in stop cues.
rel = "src/types/index.ts"
t = read(rel)
t = rep(t, "  criterion: 'memorization' | 'tajweed' | 'waqf_ibtida' | 'performance';", "  /** Criterion id from the competition's RuleSet. Kept open so each competition owns its scoring schema. */\n  criterion: string;", rel, "JudgeEvent criterion becomes rule-set driven")
t = rep(t, "  criterion: 'memorization' | 'tajweed' | 'waqf_ibtida' | 'performance' | 'custom';", "  /** RuleSet criterion id, or `custom` for an action not tied to score criteria. */\n  criterion: string;", rel, "Judge action criterion becomes rule-set driven")
t = rep(t, "  transitionCue?: { enabled:boolean; phraseArabic:string; phraseEnglish:string; autoAdvanceDelayMs:number; audioUrl?:string };", "  transitionCue?: { enabled:boolean; phraseArabic:string; phraseEnglish:string; autoAdvanceDelayMs:number; selectedPhraseIndexes?:number[]; /** legacy read-only field; no longer exposed or played */ audioUrl?:string };", rel, "transition cue selection")
write(rel, t)

rel = "src/lib/competition-config.ts"
t = read(rel)
t = rep(t, "    transitionCue: { enabled:true, phraseArabic:'حسبك، جزاك الله خيرًا', phraseEnglish:'Thank you. Please stop here.', autoAdvanceDelayMs:900, audioUrl:'' }", "    transitionCue: { enabled:true, phraseArabic:'', phraseEnglish:'', selectedPhraseIndexes:[0], autoAdvanceDelayMs:900 }", rel, "built-in cue default")
old_enabled = """export function getEnabledJudgeActions(competition: Competition) {
  return getCompetitionPolicy(competition).judging.actions.filter(a => a.enabled);
}"""
new_enabled = """export function getEnabledJudgeActions(competition: Competition) {
  const criteria=competition.ruleSet.criteria||[];
  return getCompetitionPolicy(competition).judging.actions.filter(a=>a.enabled).map(a=>{
    if(a.criterion==='custom'||criteria.some(c=>c.id===a.criterion))return a;
    const match=criteria.find(c=>c.assignedJudgeType===a.criterion||c.id===`crit-${a.criterion}`||c.id.endsWith(`-${a.criterion}`));
    return match?{...a,criterion:match.id}:a;
  });
}"""
t = rep(t, old_enabled, new_enabled, rel, "dynamic action criterion resolution")
t = sub(t, r"export const COMPETITION_TEMPLATES: CompetitionTemplate\[\] = \[.*?\n\];\n\nfunction mergePolicy", "export const COMPETITION_TEMPLATES: CompetitionTemplate[] = [];\n\nfunction mergePolicy", rel, "remove default competition templates")
write(rel, t)

rel = "src/lib/judging-integrity.ts"
t = read(rel)
replacement = """/* عبارات إنهاء الموضع المعتمدة داخل ميزان. لا تسجيل يدوي ولا نص حر:
   المنظّم يختار عبارة واحدة أو عدة عبارات أو المجموعة كلها، ويُحفظ الاختيار كفهارس. */
export const TRANSITION_PHRASES_AR=['حسبك، جزاك الله خيرًا','بارك الله فيك، قف هنا','أحسنت، نكتفي بهذا الموضع','جزاك الله خيرًا، توقّف هنا','أحسنت، بارك الله فيك','كفى، وفقك الله','شكرًا لك، نتوقف هنا','أحسنت القراءة، جزاك الله خيرًا'];
export const TRANSITION_PHRASES_EN=['Thank you. Please stop here.','Well done. Stop here, please.','That is enough for this passage. Thank you.','May God reward you. Please stop.','Well done, may God bless you.','That is enough. Thank you.','Thank you, we stop here.','Well recited. Thank you.'];
export function passageTransitionPlan(input:{
  isLastQuestion:boolean;
  ar:boolean;
  cue?:{enabled?:boolean;phraseArabic?:string;phraseEnglish?:string;selectedPhraseIndexes?:number[];autoAdvanceDelayMs?:number;audioUrl?:string};
  variantSeed?:number;
}){
  const cue=input.cue;
  const arr=input.ar?TRANSITION_PHRASES_AR:TRANSITION_PHRASES_EN;
  const legacyPhrase=input.ar?cue?.phraseArabic:cue?.phraseEnglish;
  const legacyIndex=legacyPhrase?arr.indexOf(legacyPhrase):-1;
  const requested=(cue?.selectedPhraseIndexes||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<arr.length);
  const selected=[...new Set(requested.length?requested:[legacyIndex>=0?legacyIndex:0])];
  const slot=((input.variantSeed??0)%selected.length+selected.length)%selected.length;
  const idx=selected[slot]??0;
  return {
    enabled:cue?.enabled!==false,
    variantIndex:idx,
    phrase:arr[idx],
    selectedPhraseIndexes:selected,
    delayMs:Math.max(0,Math.min(10_000,cue?.autoAdvanceDelayMs??700)),
    audioUrl:'',
    autoAdvance:!input.isLastQuestion,
  };
}
"""
t = sub(t, r"/\* عبارات إنهاء الموضع —.*?export function passageTransitionPlan\(input:\{.*?\n\}\n$", replacement, rel, "selectable stop cues")
write(rel, t)

# 2) Competition DNA: phrase selection, dynamic criteria, live certificate.
rel = "src/components/admin/CompetitionOverview.tsx"
t = read(rel)
t = rep(t, "import { ContinuityRecovery } from '../operations/ContinuityRecovery';\nimport { RealQRCode } from '../design-system/RealQRCode';", "import { ContinuityRecovery } from '../operations/ContinuityRecovery';\nimport { RealQRCode } from '../design-system/RealQRCode';\nimport { TRANSITION_PHRASES_AR, TRANSITION_PHRASES_EN } from '../../lib/judging-integrity';", rel, "transition phrase imports")
t = rep(t, "{section==='certificate'&&<CertificateSection ar={ar} policy={policy} patch={patchPolicy}/>} ", "{section==='certificate'&&<CertificateSection store={store} ar={ar} policy={policy} patch={patchPolicy}/>} ", rel, "certificate gets store context")

questions = r'''const QuestionsSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const reveal=policy.questions.secureReveal||{requireParticipantPresence:true,judgeApprovalMode:'all_assigned' as const};
 const opening=policy.questions.openingPrompt||{mode:'approved_reference_audio' as const,autoplay:true,usageScope:'opening_prompt',preferredReciter:''};
 const cue=policy.questions.transitionCue||{enabled:true,phraseArabic:'',phraseEnglish:'',selectedPhraseIndexes:[0],autoAdvanceDelayMs:900};
 const phrases=ar?TRANSITION_PHRASES_AR:TRANSITION_PHRASES_EN;
 const legacyPhrase=ar?cue.phraseArabic:cue.phraseEnglish;
 const legacyIndex=legacyPhrase?phrases.indexOf(legacyPhrase):-1;
 const validSelected=(cue.selectedPhraseIndexes||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<phrases.length);
 const selected=[...new Set(validSelected.length?validSelected:[legacyIndex>=0?legacyIndex:0])];
 const setSelected=(next:number[])=>patch(p=>{const current=p.questions.transitionCue||{enabled:true,phraseArabic:'',phraseEnglish:'',autoAdvanceDelayMs:900};p.questions.transitionCue={...current,phraseArabic:'',phraseEnglish:'',audioUrl:undefined,selectedPhraseIndexes:[...new Set(next)].sort((a,b)=>a-b)}});
 const togglePhrase=(idx:number)=>{const next=selected.includes(idx)?selected.filter(x=>x!==idx):[...selected,idx];if(next.length)setSelected(next)};
 return <div className="space-y-5"><SectionTitle title={ar?'السحب العادل والأسئلة':'FairDraw & questions'} subtitle={ar?'حدد كيف يُختار السؤال، ومتى يُكشف، وكيف تبدأ التلاوة وتنتهي دون أن يرى المحكم السؤال مبكرًا.':'Define how a question is selected, revealed, opened and ended without early exposure.'}/>
  <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4"><Control label={ar?'طريقة السحب':'Draw mode'}><TinySelect value={policy.questions.drawMode} onChange={v=>patch(p=>{p.questions.drawMode=v as any})}><option value="fairdraw">{ar?'السحب العادل القابل للتحقق':'FairDraw'}</option><option value="pure_random">{ar?'عشوائي':'Pure random'}</option><option value="manual_approved">{ar?'معتمد يدوي':'Approved manual'}</option><option value="hybrid">{ar?'هجين':'Hybrid'}</option></TinySelect></Control><NumberControl label={ar?'عدد الأسئلة':'Questions'} value={policy.questions.questionsPerParticipant} onChange={v=>patch(p=>{p.questions.questionsPerParticipant=Math.max(1,v)})}/><NumberControl label={ar?'الصعوبة المستهدفة':'Target difficulty'} step={0.1} value={policy.questions.targetDifficulty} onChange={v=>patch(p=>{p.questions.targetDifficulty=v})}/><NumberControl label={ar?'هامش الصعوبة':'Difficulty tolerance'} step={0.05} value={policy.questions.difficultyTolerance} onChange={v=>patch(p=>{p.questions.difficultyTolerance=Math.max(0,v)})}/><Control label={ar?'طريقة البداية':'Prompt mode'}><TinySelect value={policy.questions.promptMode} onChange={v=>patch(p=>{p.questions.promptMode=v as any})}><option value="configurable">{ar?'حسب الإعداد':'Configurable'}</option><option value="judge">{ar?'المحكم':'Judge'}</option><option value="certified_audio">{ar?'صوت بشري معتمد':'Certified human audio'}</option><option value="visual">{ar?'مرئي':'Visual'}</option></TinySelect></Control></div>
  <details className="mizan-surface-soft px-4 py-1"><summary className="cursor-pointer select-none list-none py-3 flex items-center justify-between gap-2 text-xs font-black text-[#59615c]"><span>{ar?'إعدادات السحب المتقدمة — اختيارية':'Advanced draw settings — optional'}</span><span className="text-[10px] font-bold text-[#656b66]">{ar?'حسب سياسة المسابقة':'competition policy'}</span></summary><div className="pb-1"><p className="text-[10px] leading-5 text-[#656b66] mb-2">{ar?'«يبدأ السحب» أي سحب سؤال المتسابق: عند تفعيله يضغط المتسابق زر السحب أمام اللجنة، وإلا يبدأه النظام. البقية ضوابط لتوزيع الأسئلة.':'“Initiates draw” means drawing the participant’s question: when on, the participant presses draw before the panel; otherwise the system starts it. The rest govern question distribution.'}</p><Toggle value={policy.questions.participantInitiatedDraw} onChange={v=>patch(p=>{p.questions.participantInitiatedDraw=v})} label={ar?'المتسابق يبدأ سحب سؤاله':'Participant initiates the question draw'}/><Toggle value={policy.questions.avoidRepeatWithinRound} onChange={v=>patch(p=>{p.questions.avoidRepeatWithinRound=v})} label={ar?'تجنب التكرار داخل الجولة':'Avoid repeats within round'}/><Toggle value={policy.questions.diversity.acrossJuz} onChange={v=>patch(p=>{p.questions.diversity.acrossJuz=v})} label={ar?'تنوع بين الأجزاء':'Across-Juz diversity'}/><Toggle value={policy.questions.diversity.acrossSurah} onChange={v=>patch(p=>{p.questions.diversity.acrossSurah=v})} label={ar?'تنوع بين السور':'Across-Surah diversity'}/><Toggle value={policy.questions.diversity.mutashabihatBalance} onChange={v=>patch(p=>{p.questions.diversity.mutashabihatBalance=v})} label={ar?'موازنة المتشابهات':'Mutashabihat balance'}/></div></details>
  <div className="grid lg:grid-cols-2 gap-3"><div className="mizan-surface p-4"><div className="mizan-kicker">{ar?'منع كشف السؤال مبكرًا':'SECURE REVEAL'}</div><div className="mt-3"><Toggle value={reveal.requireParticipantPresence} onChange={v=>patch(p=>{p.questions.secureReveal={...reveal,requireParticipantPresence:v}})} label={ar?'لا كشف قبل وجود المتسابق أمام اللجنة':'Require participant presence'}/></div><Control label={ar?'موافقة المحكمين':'Judge approval'}><TinySelect value={reveal.judgeApprovalMode} onChange={v=>patch(p=>{p.questions.secureReveal={...reveal,judgeApprovalMode:v as 'all_assigned'|'minimum'}})}><option value="all_assigned">{ar?'جميع المحكمين المكلّفين':'All assigned judges'}</option><option value="minimum">{ar?'حد أدنى محدد':'Configured minimum'}</option></TinySelect></Control>{reveal.judgeApprovalMode==='minimum'&&<div className="mt-3"><NumberControl label={ar?'الحد الأدنى للموافقات':'Minimum approvals'} value={reveal.minimumApprovals||1} onChange={v=>patch(p=>{p.questions.secureReveal={...reveal,minimumApprovals:Math.max(1,v)}})}/></div>}<p className="text-[10px] leading-5 text-[#656b66] mt-3">{ar?'الوضع الأعلى نزاهة هو موافقة كل المحكمين بعد حضور المتسابق.':'Highest-integrity mode requires every assigned judge after participant presence.'}</p></div><div className="mizan-surface p-4"><div className="mizan-kicker">{ar?'بداية التلاوة':'OPENING AYAH'}</div><div className="mt-3"><Toggle value={opening.autoplay} onChange={v=>patch(p=>{p.questions.openingPrompt={...opening,autoplay:v}})} label={ar?'تشغيل أول آية تلقائيًا بعد كشف السؤال':'Autoplay first ayah after reveal'}/></div><p className="text-[10px] leading-5 text-[#656b66] mt-3">{ar?'يُشغَّل أول آية للسؤال بصوت القارئ المعتمد المتفق عليه — لا يوجد تحويل آلي للنص القرآني إلى صوت.':'The question’s first ayah plays from the agreed approved reciter — Quran audio is never synthesized.'}</p></div></div>
  <div className="mizan-surface p-4 sm:p-5"><div className="flex flex-col sm:flex-row sm:items-start justify-between gap-3"><div><div className="mizan-kicker">{ar?'إنهاء الموضع':'PASSAGE END'}</div><h3 className="font-black mt-1">{ar?'عبارات إنهاء هادئة ومتنوعة':'Calm, varied stop cues'}</h3><p className="text-[10px] leading-5 text-[#656b66] mt-1 max-w-xl">{ar?'اختر عبارة واحدة أو عدة عبارات أو الكل. عند اختيار أكثر من واحدة يتناوب ميزان بينها تلقائيًا، ولا يوجد رفع تسجيل يدوي أو نص حر.':'Choose one, several, or all. MIZAN rotates selected cues automatically; there is no manual recording upload or free-text cue.'}</p></div><Toggle value={cue.enabled} onChange={v=>patch(p=>{p.questions.transitionCue={...cue,enabled:v}})} label={ar?'التنبيه الصوتي مفعّل':'Audio cue enabled'}/></div><div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={()=>setSelected(phrases.map((_,i)=>i))} className={`rounded-xl px-3 py-2 text-xs font-black border ${selected.length===phrases.length?'bg-[#214C40] text-white border-[#214C40]':'bg-white border-[#deddd6] text-[#214C40]'}`}>{ar?'اختيار الكل':'Select all'}</button><button type="button" onClick={()=>setSelected([selected[0]??0])} className="rounded-xl px-3 py-2 text-xs font-black border border-[#deddd6] bg-white text-[#59615c]">{ar?'واحدة فقط':'One only'}</button><span className="self-center text-[10px] text-[#656b66]">{ar?`${selected.length} مختارة`:`${selected.length} selected`}</span></div><div className="mt-3 grid md:grid-cols-2 gap-2">{phrases.map((phrase,idx)=>{const on=selected.includes(idx);return <button type="button" key={phrase} onClick={()=>togglePhrase(idx)} aria-pressed={on} className={`rounded-xl border px-3 py-3 text-start text-xs font-bold leading-5 transition ${on?'border-[#b7ccc2] bg-[#E7EEE9] text-[#214C40]':'border-[#e2e0d9] bg-[#fffefb] text-[#5e6661] hover:bg-[#f7f5ef]'}`}><span className="inline-flex w-5 h-5 me-2 rounded-full border items-center justify-center text-[10px] align-middle">{on?'✓':idx+1}</span>{phrase}</button>})}</div><div className="mt-4 max-w-sm"><NumberControl label={ar?'مهلة الانتقال بالمللي ثانية':'Transition delay (ms)'} value={cue.autoAdvanceDelayMs} onChange={v=>patch(p=>{p.questions.transitionCue={...cue,autoAdvanceDelayMs:Math.max(0,v)}})}/></div><p className="text-[10px] leading-5 text-[#656b66] mt-3">{ar?'يبدأ ميزان بالمقطع الصوتي المطابق المدمج، ثم يستخدم صوت الخادم لنفس العبارة غير القرآنية، ثم نطق الجهاز كحل أخير. لا يُرسل أي نص قرآني إلى تحويل النص إلى صوت.':'MIZAN first uses the matching built-in recording, then server speech for the same non-Quran cue, then device speech as a final fallback. Quran text is never sent to text-to-speech.'}</p></div>
 </div>;
};

'''
t = sub(t, r"const QuestionsSection=\(\{ar,policy,patch\}.*?\nconst JudgingSection=", questions + "const JudgingSection=", rel, "questions section")

judging = r'''const JudgingSection=({store,ar,policy,patch}:{store:Store;ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const r=store.competition.ruleSet;
 const setCriteria=(criteria:typeof r.criteria)=>store.updateRuleSet({criteria});
 const patchCriterion=(i:number,next:Partial<(typeof r.criteria)[number]>)=>{const criteria=[...r.criteria];criteria[i]={...criteria[i],...next};setCriteria(criteria)};
 const addCriterion=()=>setCriteria([...r.criteria,{id:`criterion-${Date.now()}`,name:'New criterion',nameArabic:'معيار جديد',maxScore:10,weight:0,assignedJudgeType:'all'}]);
 const removeCriterion=(id:string)=>{if(r.criteria.length<=1)return;setCriteria(r.criteria.filter(c=>c.id!==id));patch(p=>{p.judging.actions.forEach(a=>{if(a.criterion===id){a.criterion='custom';a.enabled=false}})})};
 return <div className="space-y-5"><SectionTitle title={ar?'سياسة التحكيم':'Judging policy'} subtitle={ar?'ابنِ معايير هذه المسابقة وأزرار محكميها كما تنص لائحتها؛ لا توجد معايير مفروضة من ميزان.':'Build this competition’s criteria and judge actions from its own rulebook; MIZAN imposes no scoring schema.'}/><div className="grid sm:grid-cols-2 gap-4"><Control label={ar?'توزيع المهام':'Judge responsibilities'}><TinySelect value={policy.judging.mode} onChange={v=>patch(p=>{p.judging.mode=v as any})}><option value="all_judges_all_criteria">{ar?'الجميع لكل المعايير':'All judges / all criteria'}</option><option value="specialized_judges">{ar?'تخصص':'Specialized'}</option><option value="hybrid">{ar?'هجين':'Hybrid'}</option></TinySelect></Control><Control label={ar?'الهوية التي يراها المحكم':'Identity'}><TinySelect value={policy.judging.identityVisibility} onChange={v=>patch(p=>{p.judging.identityVisibility=v as any})}><option value="code_only">{ar?'الكود فقط':'Code only'}</option><option value="full">{ar?'كاملة':'Full'}</option><option value="custom">{ar?'مخصصة':'Custom'}</option></TinySelect></Control><Control label={ar?'طريقة إدخال الدرجة':'Score input'}><TinySelect value={policy.judging.scoreEntryMode} onChange={v=>patch(p=>{p.judging.scoreEntryMode=v as any})}><option value="event_based">{ar?'بالأحداث':'Event based'}</option><option value="direct_score">{ar?'درجة مباشرة':'Direct score'}</option><option value="hybrid">{ar?'هجين':'Hybrid'}</option></TinySelect></Control><NumberControl label={ar?'عدد المحكمين':'Judges per panel'} value={r.judgesCountPerPanel} onChange={v=>store.updateRuleSet({judgesCountPerPanel:Math.max(1,v)})}/></div><div className="mizan-surface-soft px-4"><Toggle value={policy.judging.independentUntilLock} onChange={v=>patch(p=>{p.judging.independentUntilLock=v})} label={ar?'مستقل حتى القفل':'Independent until lock'}/><Toggle value={policy.judging.requireAudioRecording} onChange={v=>patch(p=>{p.judging.requireAudioRecording=v})} label={ar?'تسجيل الصوت مطلوب':'Audio recording required'}/><Toggle value={policy.judging.allowPhysicalJudgePad} onChange={v=>patch(p=>{p.judging.allowPhysicalJudgePad=v})} label={ar?'لوحة المحكم والاختصارات':'Judge Pad / shortcuts'}/><Toggle value={policy.judging.silentAiGuardian} onChange={v=>patch(p=>{p.judging.silentAiGuardian=v})} label={ar?'الذكاء الاصطناعي صامت للمراجعة فقط':'Silent AI review only'}/><Toggle value={policy.judging.calibrationRequired} onChange={v=>patch(p=>{p.judging.calibrationRequired=v})} label={ar?'معايرة المحكمين':'Judge calibration'}/><Toggle value={policy.judging.reserveJudgeAllowed} onChange={v=>patch(p=>{p.judging.reserveJudgeAllowed=v})} label={ar?'محكم احتياط':'Reserve judge'}/><Toggle value={policy.judging.showRunningScoreToJudge!==false} onChange={v=>patch(p=>{p.judging.showRunningScoreToJudge=v})} label={ar?'إظهار مجموع الخصم للمحكم أثناء التلاوة':'Show running deduction total to judge'}/><Toggle value={policy.judging.allowJudgeUndo!==false} onChange={v=>patch(p=>{p.judging.allowJudgeUndo=v})} label={ar?'السماح للمحكم بالتراجع عن آخر ملاحظة':'Allow judge to undo last mark'}/><Toggle value={r.dropExtremes} onChange={v=>store.updateRuleSet({dropExtremes:v})} label={ar?'إسقاط أعلى وأدنى درجة':'Drop highest and lowest'}/></div><div className="rounded-2xl border border-[#dfddd6] overflow-hidden"><div className="px-4 py-3 bg-[#f7f5ef] flex items-center justify-between gap-3"><div><div className="text-xs font-black text-[#303733]">{ar?'معايير الدرجة':'Score criteria'}</div><div className="text-[10px] text-[#656b66] mt-1">{ar?'الاسم والدرجة والوزن واختصاص المحكم كلها قابلة للبناء لهذه المسابقة.':'Names, maximums, weights and judge ownership are competition-defined.'}</div></div><button type="button" onClick={addCriterion} className="flex items-center gap-1 text-xs font-black text-[#214C40]"><Plus className="w-3.5 h-3.5"/>{ar?'معيار':'Criterion'}</button></div><div className="divide-y divide-[#e5e3dc]">{r.criteria.map((c,i)=><div key={c.id} className="p-3 grid md:grid-cols-[1fr_1fr_90px_80px_150px_auto] gap-2 items-center"><input aria-label={ar?'اسم المعيار بالعربية':'Arabic criterion name'} value={c.nameArabic} onChange={e=>patchCriterion(i,{nameArabic:e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs font-bold"/><input aria-label={ar?'اسم المعيار بالإنجليزية':'English criterion name'} value={c.name} onChange={e=>patchCriterion(i,{name:e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"/><input aria-label={ar?'الدرجة القصوى':'Maximum score'} type="number" min="0" step=".25" value={c.maxScore} onChange={e=>patchCriterion(i,{maxScore:Math.max(0,Number(e.target.value))})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"/><input aria-label={ar?'الوزن':'Weight'} type="number" min="0" max="1" step=".05" value={c.weight} onChange={e=>patchCriterion(i,{weight:Math.max(0,Math.min(1,Number(e.target.value)))})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"/><select aria-label={ar?'اختصاص المحكم':'Judge specialty'} value={c.assignedJudgeType||'all'} onChange={e=>patchCriterion(i,{assignedJudgeType:e.target.value as any})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"><option value="all">{ar?'كل المحكمين':'All judges'}</option><option value="memorization">{ar?'محكم الحفظ':'Memorization judge'}</option><option value="tajweed">{ar?'محكم التجويد':'Tajweed judge'}</option><option value="performance">{ar?'محكم الأداء':'Performance judge'}</option></select><button type="button" disabled={r.criteria.length<=1} onClick={()=>removeCriterion(c.id)} aria-label={ar?'حذف المعيار':'Remove criterion'} className="w-10 h-10 rounded-lg hover:bg-[#f2e8e5] disabled:opacity-25 text-[#9a5d54] grid place-items-center"><Trash2 className="w-4 h-4"/></button></div>)}</div></div><div><div className="flex items-center justify-between mb-2"><div><div className="text-xs font-black text-[#606662]">{ar?'أزرار المحكم':'Judge actions'}</div><div className="text-[10px] text-[#656b66] mt-1">{ar?'اربط كل زر بمعيار من معاييرك، أو اجعله مخصصًا بلا خصم على معيار.':'Bind each action to one of your criteria, or keep it custom.'}</div></div><button type="button" onClick={()=>patch(p=>p.judging.actions.push({id:`custom-${Date.now()}`,eventType:`custom_${Date.now()}`,labelArabic:'إجراء',labelEnglish:'Action',shortArabic:'إجراء',shortEnglish:'Action',criterion:r.criteria[0]?.id||'custom',penalty:0,enabled:true,icon:'custom'}))} className="flex items-center gap-1 text-xs font-bold text-[#214C40]"><Plus className="w-3.5 h-3.5"/>{ar?'إجراء':'Action'}</button></div><div className="divide-y divide-[#e5e3dc] border-y border-[#e5e3dc]">{policy.judging.actions.map((a,i)=><div key={a.id} className="py-3 grid sm:grid-cols-[1fr_160px_85px_auto_auto] gap-2 items-center"><input value={ar?a.labelArabic:a.labelEnglish} onChange={e=>patch(p=>{if(ar)p.judging.actions[i].labelArabic=e.target.value;else p.judging.actions[i].labelEnglish=e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-sm font-bold"/><select value={a.criterion} onChange={e=>patch(p=>{p.judging.actions[i].criterion=e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs">{r.criteria.map(c=><option key={c.id} value={c.id}>{ar?c.nameArabic:c.name}</option>)}<option value="custom">{ar?'مخصص بلا معيار':'Custom / no criterion'}</option></select><input aria-label={ar?'قيمة الخصم':'Penalty'} type="number" step=".25" min="0" value={a.penalty} onChange={e=>patch(p=>{p.judging.actions[i].penalty=Math.max(0,Number(e.target.value))})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"/><Chip active={a.enabled} onClick={()=>patch(p=>{p.judging.actions[i].enabled=!p.judging.actions[i].enabled})}>{a.enabled?(ar?'مفعّل':'On'):(ar?'متوقف':'Off')}</Chip><button type="button" onClick={()=>patch(p=>{p.judging.actions=p.judging.actions.filter((_,x)=>x!==i)})} aria-label={ar?'حذف الإجراء':'Remove action'} className="w-10 h-10 rounded-lg hover:bg-[#f2e8e5] text-[#9a5d54] grid place-items-center"><Trash2 className="w-4 h-4"/></button></div>)}</div></div><div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'الحد الأدنى للنجاح':'Minimum pass'} value={r.minimumPassingScore} onChange={v=>store.updateRuleSet({minimumPassingScore:v})}/><NumberControl label={ar?'مدة السؤال بالدقائق':'Question minutes'} value={r.questionDurationMinutes} onChange={v=>store.updateRuleSet({questionDurationMinutes:Math.max(1,v)})}/></div><div className="rounded-xl bg-[#E7EEE9] text-[#214C40] p-3 text-xs font-semibold">{ar?'الذكاء الاصطناعي لا يخصم أي درجة. أي إشارة آلية تتحول إلى مراجعة بشرية بعد أن يقفل المحكم تقييمه.':'AI never deducts a score. Any machine observation becomes a human review suggestion only after judges lock.'}</div></div>;
};

'''
t = sub(t, r"const JudgingSection=\(\{store,ar,policy,patch\}.*?\nconst AppealsSection=", judging + "const AppealsSection=", rel, "dynamic judging section")

certificate = r'''const CertificateSection=({store,ar,policy,patch}:{store:Store;ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const cp=policy.certificates;const brand=store.organization.brand;const title=ar?(cp.titleArabic||'شهادة'):(cp.titleEnglish||'Certificate');const award=ar?(cp.awardTextArabic||''):(cp.awardTextEnglish||'');const orgName=ar?(brand.displayNameArabic||brand.nameArabic):(brand.displayName||brand.name);const competitionName=ar?store.competition.nameArabic:store.competition.name;const verifyLink=`${typeof window!=='undefined'?window.location.origin:''}/#verify`;
 return <div className="space-y-5"><SectionTitle title={ar?'الشهادة':'Certificate'} subtitle={ar?'صمّم محتوى شهادة هادئة ورسمية، ثم يضيف ميزان التحقق الرقمي من دون أكواد تقنية مشوشة.':'Compose a calm official certificate; MIZAN adds digital verification without exposing technical noise.'}/><div className="grid xl:grid-cols-[1fr_.85fr] gap-5 items-start"><div className="space-y-4"><div className="mizan-surface-soft px-4"><Toggle value={cp.enabled} onChange={v=>patch(p=>{p.certificates.enabled=v})} label={ar?'الشهادات مفعلة':'Certificates enabled'}/><Toggle value={cp.autoIssue} onChange={v=>patch(p=>{p.certificates.autoIssue=v})} label={ar?'إصدار تلقائي بعد الإغلاق':'Auto issue after finalization'}/><Toggle value={cp.publicVerification} onChange={v=>patch(p=>{p.certificates.publicVerification=v})} label={ar?'التحقق العام مفعّل':'Public verification enabled'}/><Toggle value={cp.showScore} onChange={v=>patch(p=>{p.certificates.showScore=v})} label={ar?'إظهار الدرجة':'Show score'}/><Toggle value={cp.showRank} onChange={v=>patch(p=>{p.certificates.showRank=v})} label={ar?'إظهار الترتيب':'Show rank'}/></div><div className="grid sm:grid-cols-2 gap-4"><Control label={ar?'من يستلم':'Issue for'}><TinySelect value={cp.issueFor} onChange={v=>patch(p=>{p.certificates.issueFor=v as any})}><option value="all_participants">{ar?'كل المشاركين':'All participants'}</option><option value="qualified">{ar?'المتأهلون':'Qualified'}</option><option value="winners">{ar?'الفائزون':'Winners'}</option><option value="custom">{ar?'حسب قاعدة المسابقة':'Competition rule'}</option></TinySelect></Control><TextControl label={ar?'عنوان الشهادة':'Certificate title'} value={title} onChange={v=>patch(p=>{if(ar)p.certificates.titleArabic=v;else p.certificates.titleEnglish=v})}/></div><Control label={ar?'نص الاستحقاق':'Award text'}><textarea value={award} onChange={e=>patch(p=>{if(ar)p.certificates.awardTextArabic=e.target.value;else p.certificates.awardTextEnglish=e.target.value})} className="w-full min-h-28 rounded-xl border border-[#dcdad2] bg-white px-3 py-3 text-sm resize-none"/></Control><div><div className="flex items-center justify-between"><div><div className="text-xs font-black text-[#606662]">{ar?'التوقيعات':'Signatories'}</div><div className="text-[10px] text-[#656b66] mt-1">{ar?'تظهر كمساحات توقيع نظيفة في أسفل الشهادة.':'Rendered as clean signature blocks at the certificate foot.'}</div></div><button type="button" onClick={()=>patch(p=>{p.certificates.signatories=[...(p.certificates.signatories||[]),{name:'',title:''}]})} className="flex items-center gap-1 text-xs font-bold text-[#214C40]"><Plus className="w-3.5 h-3.5"/>{ar?'موقّع':'Signatory'}</button></div><div className="divide-y divide-[#e5e3dc] mt-2">{(cp.signatories||[]).map((s,i)=><div key={i} className="py-3 grid grid-cols-[1fr_1fr_auto] gap-2"><input placeholder={ar?'الاسم':'Name'} value={s.name} onChange={e=>patch(p=>{p.certificates.signatories![i].name=e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-sm"/><input placeholder={ar?'الصفة':'Title'} value={s.title} onChange={e=>patch(p=>{p.certificates.signatories![i].title=e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-sm"/><button type="button" onClick={()=>patch(p=>{p.certificates.signatories=p.certificates.signatories?.filter((_,x)=>x!==i)})} aria-label={ar?'حذف الموقّع':'Remove signatory'} className="w-11 h-11 rounded-lg hover:bg-[#f2e8e5] text-[#9a5d54] grid place-items-center"><Trash2 className="w-4 h-4"/></button></div>)}</div></div></div><aside className="sticky top-24"><div className="rounded-[26px] border border-[#d8cfbf] bg-[#fffdf8] p-5 sm:p-7 shadow-[0_16px_45px_rgba(66,54,35,.08)] text-center overflow-hidden relative"><div className="absolute inset-x-7 top-4 h-px bg-[#c9b58f]"/><div className="absolute inset-x-7 bottom-4 h-px bg-[#c9b58f]"/><div className="text-[9px] font-black tracking-[.22em] text-[#9B7542]">{ar?'وثيقة رسمية':'OFFICIAL DOCUMENT'}</div>{brand.logoUrl?<img src={brand.logoUrl} alt="" className="w-14 h-14 object-contain mx-auto mt-5"/>:<Award className="w-10 h-10 text-[#9B7542] mx-auto mt-5"/>}<div className="text-[11px] font-bold text-[#646965] mt-3">{orgName}</div><div className="text-[10px] text-[#858984] mt-1">{competitionName}</div><h3 className="text-2xl font-black mt-6 text-[#202622]">{title}</h3><div className="mt-5 text-[10px] text-[#777d78]">{ar?'تُمنح إلى':'Presented to'}</div><div className="mt-1 text-xl font-black text-[#214C40]">{ar?'اسم المتسابق':'Participant Name'}</div><p className="mt-5 mx-auto max-w-md text-xs leading-6 text-[#4e5551]">{award||(ar?'يظهر هنا نص الاستحقاق الذي كتبته للمسابقة.':'Your award text appears here.')}</p>{(cp.showScore||cp.showRank)&&<div className="mt-5 flex justify-center gap-2">{cp.showScore&&<Badge variant="neutral" dot={false}>{ar?'الدرجة ٩٦٫٥':'Score 96.5'}</Badge>}{cp.showRank&&<Badge variant="emerald" dot={false}>{ar?'المركز الأول':'1st place'}</Badge>}</div>}<div className="mt-8 grid grid-cols-2 gap-5">{(cp.signatories||[]).slice(0,2).map((s,i)=><div key={i} className="border-t border-[#cfc8bb] pt-2 min-h-10"><div className="text-[10px] font-bold">{s.name||(ar?'اسم الموقّع':'Signatory')}</div><div className="text-[9px] text-[#7c817d]">{s.title||(ar?'الصفة':'Title')}</div></div>)}</div>{cp.publicVerification&&<div className="mt-7 pt-4 border-t border-[#e3ded3] flex items-center justify-between gap-4 text-start"><div><div className="flex items-center gap-1 text-[10px] font-black text-[#214C40]"><ShieldCheck className="w-3.5 h-3.5"/>{ar?'قابلة للتحقق رقميًا':'Digitally verifiable'}</div><div className="text-[9px] text-[#777d78] mt-1">{ar?'امسح الرمز للتحقق من أصالة الشهادة':'Scan to verify certificate authenticity'}</div></div><div className="bg-white p-1.5 rounded-lg border border-[#e3ded3]"><RealQRCode value={verifyLink} size={54}/></div></div>}</div><div className="mt-2 text-center text-[9px] text-[#777d78]">{ar?'المعاينة تتحدث فورًا ولا تصدر شهادة حقيقية.':'Live preview only; no certificate is issued from this panel.'}</div></aside></div></div>;
};

'''
t = sub(t, r"const CertificateSection=\(\{ar,policy,patch\}.*?\nconst PrivacySection=", certificate + "const PrivacySection=", rel, "certificate designer")
write(rel, t)

# 3) JudgeOS consumes dynamic criterion ids and MIZAN-owned stop cue playback only.
rel = "src/components/judge/JudgeOS.tsx"
t = read(rel)
t = rep(t, " const judgeActions=actions.filter(a=> policy.judging.mode==='all_judges_all_criteria' || !judge || judge.specialty==='all' || a.criterion===judge.specialty || a.criterion==='custom');", " const judgeActions=actions.filter(a=>{const criterion=ruleSet.criteria.find(c=>c.id===a.criterion);return policy.judging.mode==='all_judges_all_criteria'||!judge||judge.specialty==='all'||a.criterion==='custom'||!criterion||criterion.assignedJudgeType==='all'||criterion.assignedJudgeType===judge.specialty});", rel, "dynamic action visibility")
t = rep(t, "      const criterionName=ar?CRITERION_AR[a.criterion]:a.criterion;", "      const criterion=ruleSet.criteria.find(c=>c.id===a.criterion);const criterionName=criterion?(ar?criterion.nameArabic:criterion.name):(ar?(CRITERION_AR[a.criterion]||a.criterion):a.criterion);", rel, "dynamic criterion label")
old = """ /* ترتيب مصادر عبارة الإيقاف: تسجيل بشري معتمد إن وُجد، ثم صوت مولَّد على الخادم لعبارة
    غير قرآنية، ثم نطق الجهاز كحل أخير. العبارة وحدها تُنطق — لا نص قرآني بحال. */
 const serverCue=()=>playCueUrl(`/api/public/cue-audio?text=${encodeURIComponent(transition.phrase)}`,speakFallback);
 // مقطع مسجّل مسبقًا لنفس العبارة (public/audio/cues) — الأسرع والأطبع، ويعمل دون اتصال.
 const storedCue=()=>transition.variantIndex>=0?playCueUrl(`/audio/cues/cue-${transition.variantIndex}.wav`,serverCue):serverCue();
 if(transition.audioUrl)playCueUrl(transition.audioUrl,storedCue);else storedCue()};"""
new = """ /* مصادر عبارة الإيقاف مملوكة لميزان ومطابقة للنص المختار: مقطع مدمج، ثم صوت الخادم
    لنفس العبارة غير القرآنية، ثم نطق الجهاز. لا رفع تسجيل يدوي ولا نص قرآني في TTS. */
 const serverCue=()=>playCueUrl(`/api/public/cue-audio?text=${encodeURIComponent(transition.phrase)}`,speakFallback);
 const storedCue=()=>playCueUrl(`/audio/cues/cue-${transition.variantIndex}.wav`,serverCue);
 storedCue()};"""
t = rep(t, old, new, rel, "remove manual cue playback")
t = rep(t, "     ونضبط السرعة والنبرة لنبرة ألطف. الحل النهائي الأرقى هو تشغيل تسجيل معتمد عبر audioUrl. */", "     ونضبط السرعة والنبرة لنبرة ألطف. هذا fallback فقط بعد فشل صوت ميزان المطابق. */", rel, "speech fallback comment")
write(rel, t)

# 4) Integrations managed inside MIZAN; remove Webhooks surface and duplicate identity entry.
rel = "src/components/admin/EnterpriseWorkspace.tsx"
t = read(rel)
t = rep(t, ", Webhook,", ",", rel, "remove Webhook icon import")
t = rep(t, "  identityGovernance: () => import('./IdentityGovernance'),\n", "", rel, "remove duplicate identity panel loader")
t = rep(t, "const IdentityGovernance = panel(PANELS.identityGovernance, 'IdentityGovernance');\n", "", rel, "remove duplicate identity panel")
t = sub(t, r"\n // إدارة الحسابات والصلاحيات تخص مدير الجهة.*?\n const canManageIdentities=.*?;\n", "\n", rel, "remove duplicate identity gate")
t = rep(t, "  {activeSection==='governance'&&<div className=\"space-y-4\">{canManageIdentities&&<Suspense fallback={<PanelFallback/>}><IdentityGovernance/></Suspense>}<Suspense fallback={<PanelFallback/>}><ReadinessLab onNavigate={t=>setSection(t==='field'?'operations':'integrations')}/></Suspense><Governance s={s} ar={ar}/></div>}", "  {activeSection==='governance'&&<div className=\"space-y-4\"><Suspense fallback={<PanelFallback/>}><ReadinessLab onNavigate={t=>setSection(t==='field'?'operations':'integrations')}/></Suspense><Governance s={s} ar={ar}/></div>}", rel, "remove duplicate identity render")

integrations = r'''const Integrations=({s,ar,pending}:{s:ReturnType<typeof useAppStore>;ar:boolean;pending:number})=>{
 const kinds=['email','sms','whatsapp','storage','identity','broadcast'] as const;
 const [editing,setEditing]=useState<(typeof kinds)[number]|null>(null);const [provider,setProvider]=useState('');const [serviceUrl,setServiceUrl]=useState('');
 const start=(kind:(typeof kinds)[number])=>{const cfg=s.integrations.find(i=>i.kind===kind);setEditing(kind);setProvider(cfg?.name||'');setServiceUrl(cfg?.endpoint||'')};
 const save=()=>{if(!editing)return;const name=provider.trim()||`${editing} provider`;s.configureIntegration(editing,name,true,serviceUrl.trim()||undefined);setEditing(null)};
 return <div className="space-y-4"><div className="mizan-surface p-5 sm:p-6"><div className="flex flex-col sm:flex-row sm:items-end justify-between gap-3"><div><div className="mizan-kicker">{ar?'قنوات ميزان':'MIZAN CHANNELS'}</div><h2 className="font-extrabold mt-1">{ar?'اربط خدمات الجهة من هنا':'Connect organization services here'}</h2><p className="text-xs text-[#636965] mt-2 max-w-2xl">{ar?'لا Webhooks ولا شاشة مطور. اختر القناة، اكتب اسم المزود وعنوان خدمته الآمن، واحفظها من داخل ميزان. مفاتيح المزود الحساسة لا تُكتب في المتصفح.':'No webhook console or developer surface. Choose a channel, enter the provider and secure service URL, and manage it from MIZAN. Provider secrets are never entered in the browser.'}</p></div><Badge variant={pending?'amber':'emerald'}>{pending?`${pending} ${ar?'إشعار يحتاج معالجة':'notification issues'}`:(ar?'الإشعارات هادئة':'Notifications quiet')}</Badge></div><div className="grid sm:grid-cols-2 xl:grid-cols-3 gap-3 mt-5">{kinds.map(k=>{const cfg=s.integrations.find(i=>i.kind===k);const ready=cfg?.status==='configured'&&cfg.enabled;return <div key={k} className={`rounded-2xl border p-4 transition ${ready?'border-[#cadbd2] bg-[#f7faf8]':'border-[#e2e0d9] bg-[#fffefb]'}`}><div className="flex items-center justify-between gap-3"><div className="flex items-center gap-2"><span className={`w-9 h-9 rounded-xl grid place-items-center ${ready?'bg-[#E7EEE9] text-[#214C40]':'bg-[#f1efe9] text-[#666d68]'}`}><Cable className="w-4 h-4"/></span><div><div className="text-sm font-black">{channelLabel(k,ar)}</div><div className="text-[10px] text-[#656b66] mt-0.5">{ready?(ar?'محفوظ ومفعّل':'Saved & enabled'):cfg?(ar?'يحتاج إكمال الربط':'Setup incomplete'):(ar?'غير مربوط':'Not connected')}</div></div></div><span className={`w-2.5 h-2.5 rounded-full ${ready?'bg-[#2F6555]':'bg-[#c9c5bb]'}`}/></div>{cfg?.name&&<div className="text-[10px] text-[#656b66] mt-3 truncate">{cfg.name}</div>}<div className="mt-3 flex gap-2"><Button size="sm" variant="outline" onClick={()=>start(k)}>{cfg?(ar?'إدارة':'Manage'):(ar?'ربط':'Connect')}</Button>{cfg&&<Button size="sm" variant="ghost" onClick={()=>s.configureIntegration(k,cfg.name,!cfg.enabled,cfg.endpoint)}>{cfg.enabled?(ar?'إيقاف':'Disable'):(ar?'تفعيل':'Enable')}</Button>}</div></div>})}</div>{editing&&<div className="mt-5 rounded-2xl border border-[#d9d7d0] bg-[#f7f5ef] p-4"><div className="flex items-center justify-between gap-3"><div><div className="text-sm font-black">{ar?`ربط ${channelLabel(editing,true)}`:`Connect ${editing}`}</div><div className="text-[10px] text-[#656b66] mt-1">{ar?'بيانات الربط غير السرية فقط؛ الأسرار تبقى في بيئة الخادم.':'Non-secret connection metadata only; credentials remain server-side.'}</div></div><button type="button" onClick={()=>setEditing(null)} className="text-xs font-bold text-[#656b66]">{ar?'إغلاق':'Close'}</button></div><div className="grid sm:grid-cols-2 gap-3 mt-4"><label><span className="block text-[10px] font-black text-[#656b66] mb-1">{ar?'اسم المزود أو الحساب':'Provider / account name'}</span><input value={provider} onChange={e=>setProvider(e.target.value)} className="mizan-input" placeholder={ar?'مثال: بوابة الرسائل الرسمية':'Official messaging provider'}/></label><label><span className="block text-[10px] font-black text-[#656b66] mb-1">{ar?'عنوان الخدمة الآمن':'Secure service URL'}</span><input dir="ltr" value={serviceUrl} onChange={e=>setServiceUrl(e.target.value)} className="mizan-input" placeholder="https://…"/></label></div><div className="mt-3 flex items-center justify-between gap-3"><span className="text-[10px] text-[#656b66]">{serviceUrl&&!/^https:\/\//i.test(serviceUrl)?(ar?'العنوان يجب أن يبدأ بـ https://':'URL must start with https://'):''}</span><Button size="sm" disabled={!provider.trim()||!/^https:\/\//i.test(serviceUrl)} onClick={save}>{ar?'حفظ الربط':'Save connection'}</Button></div></div>}</div><div className="mizan-surface p-5"><div className="flex items-center justify-between gap-3"><div className="flex items-center gap-2"><Bell className="w-4 h-4 text-[#2F6555]"/><h2 className="font-extrabold">{ar?'مركز الإشعارات':'Notification Center'}</h2></div><span className="text-[10px] text-[#656b66]">{s.notifications.length}</span></div><div className="mt-4 divide-y divide-[#e6e4dd]">{s.notifications.slice(0,8).map(n=><div key={n.id} className="py-3 grid grid-cols-[auto_1fr_auto] gap-3 items-center"><span className={`w-2 h-2 rounded-full ${n.status==='sent'?'bg-[#2F6555]':n.status==='failed'?'bg-[#A34D43]':'bg-[#9B7542]'}`}/><div className="min-w-0"><div className="text-xs font-bold truncate">{notificationTemplateLabel(n.templateKey,ar)}</div><div className="text-[10px] text-[#656b66] truncate">{channelLabel(n.channel,ar)} · {uiToken(n.status,ar)}{n.error?` · ${n.error}`:''}</div></div>{n.status==='failed'&&<Button size="sm" variant="ghost" onClick={()=>s.retryNotification(n.id)}>{ar?'إعادة':'Retry'}</Button>}</div>)}{!s.notifications.length&&<Empty ar={ar}/>}</div></div></div>
}
'''
t = sub(t, r"const Integrations=\(\{s,ar,pending\}.*?\nconst Field=", integrations + "const Field=", rel, "self-service integrations")

governance = r'''const Governance=({s,ar}:{s:ReturnType<typeof useAppStore>;ar:boolean})=>{const [reason,setReason]=useState('');const backup=s.backups[0];return <div className="grid xl:grid-cols-3 gap-4"><div className="mizan-surface p-5"><DatabaseBackup className="w-4 h-4 text-[#2F6555]"/><h2 className="font-extrabold mt-3">{ar?'سلامة بيانات المسابقة':'Competition data integrity'}</h2><p className="text-xs text-[#646965] mt-2 leading-5">{backup?(ar?'آخر نقطة استعادة محفوظة ولها بصمة تحقق؛ يمكن كشف أي تلف أو تغيير غير متوقع.':'Latest restore point carries an integrity fingerprint so corruption or unexpected change can be detected.'):(ar?'أنشئ نقطة استعادة موثوقة قبل التشغيل أو قبل تغيير مهم.':'Create a trusted restore point before live operation or a major change.')}</p>{backup&&<div className="mt-3"><Badge variant="emerald">{ar?'سلامة قابلة للتحقق':'Verifiable integrity'}</Badge><div className="text-[9px] text-[#777d78] mt-2">{ar?'تم الحفظ':'Saved'} {new Date(backup.createdAt).toLocaleString(ar?'ar-KW':'en')}</div></div>}<Button size="sm" className="mt-4" onClick={()=>s.createBackup()}>{ar?'إنشاء نقطة استعادة':'Create restore point'}</Button></div><div className="mizan-surface p-5"><Copy className="w-4 h-4 text-[#2F6555]"/><h2 className="font-extrabold mt-3">{ar?'إصدار جديد من المسابقة':'New competition edition'}</h2><p className="text-xs text-[#646965] mt-2 leading-5">{ar?'ينقل هيكل المسابقة وقواعدها فقط، ثم يصفر التواريخ والأعداد والتجميد لتبدأ إصدارًا مستقلًا ونظيفًا.':'Carries the structure and rules only, then clears dates, counts and freezes for a clean independent edition.'}</p><Button size="sm" variant="outline" className="mt-4" onClick={()=>s.cloneCompetition()}>{ar?'بدء إصدار جديد':'Start new edition'}</Button></div><div className="mizan-surface p-5"><Download className="w-4 h-4 text-[#2F6555]"/><h2 className="font-extrabold mt-3">{ar?'تصدير موثّق':'Portable export'}</h2><p className="text-xs text-[#646965] mt-2">{ar?'ملف قابل للنقل والاستعادة عند الحاجة.':'Portable competition snapshot for controlled restore.'}</p><Button size="sm" variant="outline" className="mt-4" onClick={()=>{const blob=new Blob([s.exportCompetitionSnapshot()],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mizan-competition-export.json';a.click();URL.revokeObjectURL(a.href)}}>{ar?'تصدير ملف':'Export file'}</Button></div><div className="mizan-surface p-5 xl:col-span-3"><div className="flex items-center gap-2"><ShieldCheck className="w-4 h-4 text-[#2F6555]"/><h2 className="font-extrabold">{ar?'جلسة دعم مراقبة':'Audited support session'}</h2></div><div className="mt-4 flex gap-2"><input value={reason} onChange={e=>setReason(e.target.value)} className="min-w-0 flex-1 rounded-xl border border-[#ddd] px-3 py-2.5 text-sm" placeholder={ar?'سبب طلب الدعم':'Support reason'}/><Button size="sm" disabled={!reason.trim()} onClick={()=>{s.requestSupportSession(reason);setReason('')}}>{ar?'طلب':'Request'}</Button></div></div></div>}
'''
t = sub(t, r"const Governance=\(\{s,ar\}.*?\nconst State=", governance + "const State=", rel, "data integrity and new edition")
write(rel, t)

# 5) Store semantics: self-service connection profile and a true new edition.
rel = "src/lib/store.ts"
t = read(rel)
old_config = """  const configureIntegration = (kind: IntegrationConfig['kind'], name:string, enabled=true, endpoint?:string) => {
    const existing=globalState.integrations.findIndex(i=>i.kind===kind);
    const cleanEndpoint=endpoint?.trim();
    const looksPlaceholder=!cleanEndpoint||cleanEndpoint.startsWith('internal://')||cleanEndpoint.includes('example.')||cleanEndpoint.includes('localhost');
    // Registering an adapter is not proof that a credentialed provider is live.
    // Development/UI configuration therefore stays NOT_CONFIGURED until a deployed backend health check promotes it.
    const previous=existing>=0?globalState.integrations[existing]:undefined;
    const item:IntegrationConfig={id:previous?.id||newId('int'),organizationId:globalState.competition.organizationId,kind,name,enabled,status:previous?.status==='configured'&&!looksPlaceholder?'configured':'not_configured',endpoint:looksPlaceholder?undefined:cleanEndpoint,lastCheckedAt:new Date().toISOString()};
    if(existing>=0)globalState.integrations[existing]=item;else globalState.integrations=[item,...globalState.integrations];
    globalState.auditLogs=[{id:newId('aud'),timestamp:new Date().toISOString(),organizationId:globalState.competition.organizationId,competitionId:globalState.competition.id,actorId:globalState.currentUser.id,actorName:globalState.currentUser.name,actorRole:globalState.currentUser.role,action:'INTEGRATION_ADAPTER_CONFIGURED',entityType:'Integration',entityId:item.id,humanSummaryArabic:`تهيئة محول ${name} دون ادعاء اتصال مزود خارجي`,humanSummaryEnglish:`Configured ${name} adapter without claiming external provider connectivity`,currentStateHash:`integration:${item.id}:${item.status}`},...globalState.auditLogs];
    notify(); return item;
  };"""
new_config = """  const configureIntegration = (kind: IntegrationConfig['kind'], name:string, enabled=true, endpoint?:string) => {
    const existing=globalState.integrations.findIndex(i=>i.kind===kind);
    const cleanEndpoint=endpoint?.trim();
    const safeEndpoint=!!cleanEndpoint&&/^https:\/\//i.test(cleanEndpoint)&&!cleanEndpoint.includes('example.')&&!cleanEndpoint.includes('localhost');
    const previous=existing>=0?globalState.integrations[existing]:undefined;
    const item:IntegrationConfig={id:previous?.id||newId('int'),organizationId:globalState.competition.organizationId,kind,name:name.trim(),enabled,status:enabled&&safeEndpoint?'configured':'not_configured',secretRef:previous?.secretRef,endpoint:safeEndpoint?cleanEndpoint:undefined,lastCheckedAt:new Date().toISOString()};
    if(existing>=0)globalState.integrations[existing]=item;else globalState.integrations=[item,...globalState.integrations];
    globalState.auditLogs=[{id:newId('aud'),timestamp:new Date().toISOString(),organizationId:globalState.competition.organizationId,competitionId:globalState.competition.id,actorId:globalState.currentUser.id,actorName:globalState.currentUser.name,actorRole:globalState.currentUser.role,action:'INTEGRATION_PROFILE_UPDATED',entityType:'Integration',entityId:item.id,humanSummaryArabic:`تحديث ربط ${item.name} من داخل ميزان: ${item.status}`,humanSummaryEnglish:`Updated ${item.name} connection profile inside MIZAN: ${item.status}`,currentStateHash:`integration:${item.id}:${item.status}:${item.enabled}`},...globalState.auditLogs];
    notify(); return item;
  };"""
t = rep(t, old_config, new_config, rel, "self-service integration profile")
old_clone = "  const cloneCompetition=(nameArabic?:string,nameEnglish?:string)=>{const base=JSON.parse(JSON.stringify(globalState.competition)) as Competition;base.id=newId('comp');base.nameArabic=nameArabic||`${base.nameArabic} — نسخة`;base.name=nameEnglish||`${base.name} — Copy`;base.status='draft';base.totalRegistered=0;base.totalApproved=0;base.totalAttended=0;base.policy={...getCompetitionPolicy(base),updatedAt:new Date().toISOString(),frozenAt:undefined};base.categories=base.categories.map(c=>({...c,id:newId('cat'),competitionId:base.id}));globalState.competitions=[base,...globalState.competitions];globalState.competition=base;notify();return base;};"
new_clone = """  const cloneCompetition=(nameArabic?:string,nameEnglish?:string)=>{
    const source=globalState.competition;const base=JSON.parse(JSON.stringify(source)) as Competition;base.id=newId('comp');
    base.nameArabic=nameArabic||source.nameArabic;base.name=nameEnglish||source.name;base.edition='';
    base.status='draft';base.startDate='';base.endDate='';base.registrationStartDate='';base.registrationEndDate='';
    base.totalRegistered=0;base.totalApproved=0;base.totalAttended=0;base.currentDay=0;
    const rule={...base.ruleSet,id:newId('rule'),frozenAt:undefined,version:`${base.ruleSet.version}-new-edition`};
    base.ruleSet=rule;base.ruleSets=[rule];base.policy={...getCompetitionPolicy(base),updatedAt:new Date().toISOString(),frozenAt:undefined};
    base.categories=base.categories.map(c=>({...c,id:newId('cat'),competitionId:base.id,ruleSetId:rule.id}));
    base.readinessChecklist={datesConfigured:false,categoriesConfigured:base.categories.length>0,ruleSetFrozen:false,judgesAssigned:false,quranSourceLocked:false,devicesRegistered:false,certificatesReady:false};
    globalState.competitions=[base,...globalState.competitions];globalState.competition=base;
    globalState.auditLogs=[{id:newId('aud'),timestamp:new Date().toISOString(),organizationId:base.organizationId,competitionId:base.id,actorId:globalState.currentUser.id,actorName:globalState.currentUser.name,actorRole:globalState.currentUser.role,action:'COMPETITION_NEW_EDITION_CREATED',entityType:'Competition',entityId:base.id,humanSummaryArabic:`بدء إصدار جديد مستقل من ${source.nameArabic}`,humanSummaryEnglish:`Started a clean new edition of ${source.name}`,currentStateHash:`edition:${base.id}`},...globalState.auditLogs];
    notify();return base;
  };"""
t = rep(t, old_clone, new_clone, rel, "new edition semantics")
write(rel, t)

